function AdvSection(){
  const rides = [
    {
      title: "Giant Swing",
      tag: "50+ Ft Height",
      desc: "Experience Coorg's first giant swing soaring 50+ feet over lush green plantation canopies with thrilling valley views.",
      img: "/images-sky-16/giant swing.jpg"
    },
    {
      title: "Rocket Launcher",
      tag: "High Adrenaline",
      desc: "Launch skyward with intense acceleration under international safety-certified harnesses and expert operators.",
      img: "/images-sky-16/rocketlauncher.jpg"
    },
    {
      title: "Bull Ride",
      tag: "Mechanical Rodeo",
      desc: "Test your balance and endurance on our electric mechanical rodeo bull. Incredible laughter and fun for friends and family!",
      img: "/images-sky-16/bullride.jpg"
    }
  ];

  return f.jsxs("section", {
    id: "adventure",
    className: "py-16 px-4 sm:px-6 lg:px-8 text-white relative border-b border-black overflow-hidden",
    style: { backgroundColor: "#140804" },
    children: [
      f.jsxs("div", {
        className: "max-w-7xl mx-auto text-center relative z-10",
        children: [
          f.jsxs("div", {
            className: "inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-cafe-accent/15 border border-cafe-accent/30 text-cafe-accent font-mono text-xs font-bold uppercase tracking-widest mb-3",
            children: [f.jsx("span", { children: "🌲" }), f.jsx("span", { children: "Ultimate Thrills" })]
          }),
          f.jsx("h2", {
            className: "text-3xl sm:text-4xl font-serif font-bold text-white tracking-tight mb-2",
            children: "Feel The Rush"
          }),
          f.jsx("p", {
            className: "text-xs sm:text-sm text-amber-100/70 italic max-w-xl mx-auto mb-10 font-serif",
            children: '"Adventure is out there. You just have to be fast enough to catch it."'
          }),
          f.jsx("div", {
            className: "adventure-grid text-left",
            children: rides.map((r, idx) => f.jsxs("div", {
              key: idx,
              className: "adventure-card group",
              children: [
                f.jsxs("div", {
                  className: "adventure-card-img-wrap",
                  children: [
                    f.jsx("img", {
                      src: r.img,
                      alt: r.title,
                      className: "adventure-card-img"
                    }),
                    f.jsx("div", {
                      className: "absolute top-3 right-3 bg-cafe-accent text-white text-[10px] font-mono font-bold px-2.5 py-0.5 rounded-full uppercase tracking-wider shadow-md z-10",
                      children: r.tag
                    })
                  ]
                }),
                f.jsxs("div", {
                  className: "p-5 space-y-2 flex-1 flex flex-col justify-between",
                  children: [
                    f.jsx("h3", {
                      className: "font-serif text-xl font-bold text-white",
                      children: r.title
                    }),
                    f.jsx("p", {
                      className: "text-xs sm:text-sm text-amber-100/80 leading-relaxed font-sans",
                      children: r.desc
                    })
                  ]
                })
              ]
            }))
          })
        ]
      })
    ]
  });
}

